export const fresh=()=>({version:1,coins:0,diamonds:0,treadmill:0,habitat:0,pets:[],bossDrops:[],eggs:0,calm:true,avatar:{color:0x368cfa,hat:0,wings:0},checkpoint:0});
export function normalize(s){if(!s||s.version!==1)throw Error('Versão de save incompatível');const d={...fresh(),...s};for(const k of ['coins','diamonds','treadmill','habitat','eggs'])if(!Number.isFinite(d[k])||d[k]<0)throw Error('Save inválido');if(!Array.isArray(d.pets))throw Error('Pets inválidos');return d}
export class SaveSystem{constructor(){this.data=fresh();this.blocked=false;for(const key of ['caleb-save','caleb-backup']){try{const raw=localStorage.getItem(key);if(raw){this.data=normalize(JSON.parse(raw));break}}catch(e){console.warn(e)}}this.timer=setInterval(()=>this.save(),5000);addEventListener('pagehide',()=>this.save());document.addEventListener('visibilitychange',()=>{if(document.hidden)this.save()})}save(){try{const old=localStorage.getItem('caleb-save');if(old){try{normalize(JSON.parse(old));localStorage.setItem('caleb-backup',old)}catch{}}localStorage.setItem('caleb-save',JSON.stringify(this.data));return true}catch(e){console.error('Falha ao salvar',e);return false}}spend(n){if(n<0||this.data.coins<n)return false;this.data.coins-=n;this.save();return true}add(n){this.data.coins=Math.min(Number.MAX_SAFE_INTEGER,this.data.coins+Math.max(0,n));this.save()}}
